import { describe, expect, it } from "vitest";
import {
	HEVY_ENDPOINT_TEMPLATES,
	canonicalEndpointIdentity,
	diagnosticEndpointIdentity,
	expectedGet404Outcome,
	isExpectedMutation404,
	isTransientRetryFailure,
	isTransientRetryStatus,
	metricEndpointIdentity,
	resolveHevyEndpoint,
} from "./endpoint-policy.js";

describe("Hevy endpoint policy", () => {
	it("resolves every generated endpoint template", () => {
		expect(HEVY_ENDPOINT_TEMPLATES).toHaveLength(14);
		for (const endpoint of HEVY_ENDPOINT_TEMPLATES) {
			expect(resolveHevyEndpoint(endpoint)).toMatchObject({
				known: true,
				canonical: endpoint,
				diagnostic: endpoint,
				metric: endpoint,
			});
		}
	});

	it("resolves each dynamic route with exactly one non-empty segment", () => {
		const routes = [
			["/v1/body_measurements/2026-01-01", "/v1/body_measurements/:date"],
			[
				"/v1/exercise_history/template-id",
				"/v1/exercise_history/:exerciseTemplateId",
			],
			[
				"/v1/exercise_templates/template-id",
				"/v1/exercise_templates/:exerciseTemplateId",
			],
			["/v1/routine_folders/folder-id", "/v1/routine_folders/:folderId"],
			["/v1/routines/routine-id", "/v1/routines/:routineId"],
			["/v1/workouts/workout-id", "/v1/workouts/:workoutId"],
		] as const;
		for (const [path, endpoint] of routes) {
			expect(canonicalEndpointIdentity(path)).toBe(endpoint);
		}
	});

	it("takes static precedence and strips query and fragment identity suffixes", () => {
		expect(canonicalEndpointIdentity("/v1/workouts/count?secret=id")).toBe(
			"/v1/workouts/count",
		);
		expect(canonicalEndpointIdentity("/v1/workouts/events#fragment")).toBe(
			"/v1/workouts/events",
		);
		expect(canonicalEndpointIdentity("/v1/workouts/abc?x=1#fragment")).toBe(
			"/v1/workouts/:workoutId",
		);
	});

	it("fails closed for private, prefix, extra-segment, and trailing-slash paths", () => {
		for (const endpoint of [
			"",
			"/v1/private/secret",
			"/v1/workouts/count/near-match",
			"/v1/workouts/abc/extra",
			"/v1/workouts/",
			"/v1/body_measurements/",
			"/v1/exercise_history/",
			"/v1/exercise_templates/",
			"/v1/routine_folders/",
			"/v1/routines/",
		]) {
			expect(canonicalEndpointIdentity(endpoint)).toBe("unknown");
			expect(diagnosticEndpointIdentity(endpoint)).toBeUndefined();
			expect(metricEndpointIdentity(endpoint)).toBe("unknown");
		}
		expect(canonicalEndpointIdentity("/v1/workouts")).toBe("/v1/workouts");
	});

	it("keeps the distinct GET 404 absence facts", () => {
		expect(
			expectedGet404Outcome("/v1/exercise_history/template-id", "GET", 404),
		).toBe("not_found");
		expect(
			expectedGet404Outcome("/v1/workouts", "GET", 404, 1),
		).toBeUndefined();
		expect(expectedGet404Outcome("/v1/workouts", "GET", 404, 2)).toBe(
			"end_of_list",
		);
		expect(
			expectedGet404Outcome("/v1/workouts", "POST", 404, 2),
		).toBeUndefined();
	});

	it("applies mutation 404 policy only to known mutable endpoints", () => {
		expect(isExpectedMutation404("/v1/routines/routine-id", "PUT", 404)).toBe(
			true,
		);
		expect(
			isExpectedMutation404("/v1/exercise_history/template-id", "POST", 404),
		).toBe(false);
		expect(isExpectedMutation404("/v1/private/secret", "POST", 404)).toBe(
			false,
		);
		expect(isExpectedMutation404("/v1/routines/routine-id", "GET", 404)).toBe(
			false,
		);
	});

	it("classifies retry boundaries without owning retry execution", () => {
		for (const status of [undefined, 408, 429, 500, 599]) {
			expect(isTransientRetryStatus(status)).toBe(true);
		}
		for (const status of [400, 404, 499, 600]) {
			expect(isTransientRetryStatus(status)).toBe(false);
		}
		expect(isTransientRetryFailure(503, "HEVY_RETRY_EXHAUSTED")).toBe(false);
		expect(isTransientRetryFailure(503, "HEVY_REQUEST_ABORTED")).toBe(false);
		expect(isTransientRetryFailure(503)).toBe(true);
	});
});

import {
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
} from "./hevy-http-error.js";

/** Canonical identities for every endpoint template in the generated Hevy client. */
export type HevyEndpointTemplate =
	| "/v1/body_measurements"
	| "/v1/body_measurements/:date"
	| "/v1/exercise_history/:exerciseTemplateId"
	| "/v1/exercise_templates"
	| "/v1/exercise_templates/:exerciseTemplateId"
	| "/v1/routine_folders"
	| "/v1/routine_folders/:folderId"
	| "/v1/routines"
	| "/v1/routines/:routineId"
	| "/v1/user/info"
	| "/v1/workouts"
	| "/v1/workouts/:workoutId"
	| "/v1/workouts/count"
	| "/v1/workouts/events";

export type HevyEndpointIdentity = HevyEndpointTemplate | "unknown";
export type HevyDiagnosticEndpoint = HevyEndpointTemplate;
export type HevyMetricEndpoint = HevyEndpointTemplate | "unknown";

export const HEVY_ENDPOINT_TEMPLATES: readonly HevyEndpointTemplate[] = [
	"/v1/body_measurements",
	"/v1/body_measurements/:date",
	"/v1/exercise_history/:exerciseTemplateId",
	"/v1/exercise_templates",
	"/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders",
	"/v1/routine_folders/:folderId",
	"/v1/routines",
	"/v1/routines/:routineId",
	"/v1/user/info",
	"/v1/workouts",
	"/v1/workouts/:workoutId",
	"/v1/workouts/count",
	"/v1/workouts/events",
];

export interface HevyEndpointResolution {
	readonly known: boolean;
	readonly canonical: HevyEndpointIdentity;
	readonly diagnostic: HevyDiagnosticEndpoint | undefined;
	readonly metric: HevyMetricEndpoint;
}

const STATIC_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/user/info",
	"/v1/workouts",
	"/v1/workouts/count",
	"/v1/workouts/events",
]);

const DYNAMIC_ENDPOINTS: readonly (readonly [string, HevyEndpointTemplate])[] =
	[
		["/v1/body_measurements/", "/v1/body_measurements/:date"],
		["/v1/exercise_history/", "/v1/exercise_history/:exerciseTemplateId"],
		["/v1/exercise_templates/", "/v1/exercise_templates/:exerciseTemplateId"],
		["/v1/routine_folders/", "/v1/routine_folders/:folderId"],
		["/v1/routines/", "/v1/routines/:routineId"],
		["/v1/workouts/", "/v1/workouts/:workoutId"],
	];

function identityPath(value: string): string {
	const query = value.search(/[?#]/);
	return query < 0 ? value : value.slice(0, query);
}

/** Resolve a raw request path or a canonical template without exposing IDs. */
export function resolveHevyEndpoint(path: string): HevyEndpointResolution {
	const candidate = identityPath(path);
	let endpoint: HevyEndpointTemplate | undefined;
	if (STATIC_ENDPOINTS.has(candidate as HevyEndpointTemplate)) {
		endpoint = candidate as HevyEndpointTemplate;
	} else {
		for (const [prefix, template] of DYNAMIC_ENDPOINTS) {
			const id = candidate.slice(prefix.length);
			if (candidate.startsWith(prefix) && id.length > 0 && !id.includes("/")) {
				endpoint = template;
				break;
			}
		}
	}
	if (
		!endpoint &&
		HEVY_ENDPOINT_TEMPLATES.includes(candidate as HevyEndpointTemplate)
	) {
		endpoint = candidate as HevyEndpointTemplate;
	}
	return endpoint
		? {
				known: true,
				canonical: endpoint,
				diagnostic: endpoint,
				metric: endpoint,
			}
		: {
				known: false,
				canonical: "unknown",
				diagnostic: undefined,
				metric: "unknown",
			};
}

export function canonicalEndpointIdentity(path: string): HevyEndpointIdentity {
	return resolveHevyEndpoint(path).canonical;
}

export function diagnosticEndpointIdentity(
	path: string,
): HevyDiagnosticEndpoint | undefined {
	return resolveHevyEndpoint(path).diagnostic;
}

export function metricEndpointIdentity(path: string): HevyMetricEndpoint {
	return resolveHevyEndpoint(path).metric;
}

export type ExpectedGet404Outcome = "not_found" | "end_of_list";

const RESOURCE_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements/:date",
	"/v1/exercise_history/:exerciseTemplateId",
	"/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders/:folderId",
	"/v1/routines/:routineId",
	"/v1/workouts/:workoutId",
]);
const LIST_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/workouts",
	"/v1/workouts/events",
]);

/** Return the bounded meaning of a GET 404, if it is an expected absence. */
export function expectedGet404Outcome(
	endpoint: string,
	method: string,
	status: number | undefined,
	page?: number,
): ExpectedGet404Outcome | undefined {
	if (status !== 404 || method.toUpperCase() !== "GET") return undefined;
	const resolved = resolveHevyEndpoint(endpoint).canonical;
	if (RESOURCE_404_ENDPOINTS.has(resolved as HevyEndpointTemplate)) {
		return "not_found";
	}
	if (
		page !== undefined &&
		page > 1 &&
		LIST_404_ENDPOINTS.has(resolved as HevyEndpointTemplate)
	) {
		return "end_of_list";
	}
	return undefined;
}

export type Mutation404Policy = "expected" | "unexpected";
const MUTATION_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/body_measurements/:date",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/routines/:routineId",
	"/v1/workouts",
	"/v1/workouts/:workoutId",
]);

/** Mutating 404s are expected only for known mutable endpoint identities. */
export function mutation404Policy(
	endpoint: string,
	method: string,
	status: number | undefined,
): Mutation404Policy {
	return status === 404 &&
		method.toUpperCase() !== "GET" &&
		MUTATION_404_ENDPOINTS.has(
			resolveHevyEndpoint(endpoint).canonical as HevyEndpointTemplate,
		)
		? "expected"
		: "unexpected";
}

export function isExpectedMutation404(
	endpoint: string,
	method: string,
	status: number | undefined,
): boolean {
	return mutation404Policy(endpoint, method, status) === "expected";
}

const NON_RETRYABLE_CODES = new Set([
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
]);

export function isTransientRetryStatus(status: number | undefined): boolean {
	return (
		status === undefined ||
		status === 408 ||
		status === 429 ||
		(status >= 500 && status <= 599)
	);
}

export function isTransientRetryCode(code: string | undefined): boolean {
	return code === undefined || !NON_RETRYABLE_CODES.has(code);
}

/** Shared status/code classification; execution layers still own retry budgets. */
export function isTransientRetryFailure(
	status: number | undefined,
	code?: string,
): boolean {
	return isTransientRetryCode(code) && isTransientRetryStatus(status);
}

/**
 * Runtime-neutral execution control shared by every Hevy adapter.
 *
 * The client owns this vocabulary so adapters can only present the same
 * outcome; they cannot accidentally grow incompatible retry/error taxonomies.
 */

export type HevyOperationSafety =
	| "read"
	| "idempotent-write"
	| "non-idempotent-write";

export type HevyRequestPhase =
	| "before-dispatch"
	| "dispatch"
	| "response-headers"
	| "response-content"
	| "backoff"
	| "completed";

export type HevyCommitState = "not_sent" | "confirmed" | "unknown";

export type HevyExecutionOutcome =
	| "success"
	| "expected"
	| "retryable_failure"
	| "terminal_failure"
	| "cancelled"
	| "deadline_exceeded";

export interface HevyExecutionOutcomeDetails {
	readonly outcome: HevyExecutionOutcome;
	readonly phase: HevyRequestPhase;
	readonly operation_safety: HevyOperationSafety;
	readonly commit_state: HevyCommitState;
	readonly safe_to_retry: boolean;
	readonly status?: number;
	readonly code?: string;
}

/** Caller-owned control for one logical operation (not one retry attempt). */
export interface HevyExecutionControl {
	readonly signal?: AbortSignal;
	/** Absolute epoch milliseconds supplied by the caller; never reset. */
	readonly deadline?: number;
}

export interface HevyExecutionOptions extends HevyExecutionControl {
	/** Per-operation timeout in milliseconds; overrides the client default. */
	readonly timeoutMs?: number;
}

/** Request options shared by the curated client and generated adapters. */
export interface HevyRequestOptions extends HevyExecutionOptions {}

export function isDeadlineExceeded(deadline: number | undefined): boolean {
	return deadline !== undefined && Date.now() >= deadline;
}

export function remainingDeadlineMs(deadline: number | undefined): number {
	return deadline === undefined
		? Number.POSITIVE_INFINITY
		: deadline - Date.now();
}

export function operationSafetyForMethod(method: string): HevyOperationSafety {
	const normalizedMethod = method.toUpperCase();
	if (["GET", "HEAD", "OPTIONS"].includes(normalizedMethod)) {
		return "read";
	}
	if (["PUT", "DELETE"].includes(normalizedMethod)) {
		return "idempotent-write";
	}
	return "non-idempotent-write";
}

export function canRetryOperation(
	safety: HevyOperationSafety,
	phase: HevyRequestPhase,
): boolean {
	if (safety === "non-idempotent-write") return false;
	return (
		phase === "before-dispatch" ||
		phase === "dispatch" ||
		phase === "response-headers" ||
		phase === "response-content" ||
		phase === "backoff"
	);
}

export function commitStateFor(
	safety: HevyOperationSafety,
	phase: HevyRequestPhase,
	confirmed: boolean,
): HevyCommitState {
	if (safety === "read") return confirmed ? "confirmed" : "not_sent";
	if (confirmed) return "confirmed";
	return phase === "before-dispatch" ? "not_sent" : "unknown";
}

export interface HevyExecutionSignal {
	readonly signal: AbortSignal;
	readonly abort: (reason?: Error | string | DOMException) => void;
	readonly cleanup: () => void;
	readonly deadlineTriggered: () => boolean;
}

/**
 * Build a signal that follows both caller cancellation and one absolute
 * deadline. The returned cleanup function must be called when the operation
 * completes so a long-lived server does not retain timers/listeners.
 */
export function createExecutionSignal(
	control: HevyExecutionControl,
): HevyExecutionSignal {
	const controller = new AbortController();
	let deadlineTriggered = false;
	const abortFromCaller = () => {
		if (!controller.signal.aborted) controller.abort(control.signal?.reason);
	};
	if (control.signal?.aborted) abortFromCaller();
	else
		control.signal?.addEventListener("abort", abortFromCaller, { once: true });
	let timer: ReturnType<typeof setTimeout> | undefined;
	if (control.deadline !== undefined) {
		const delay = Math.max(0, control.deadline - Date.now());
		timer = setTimeout(() => {
			deadlineTriggered = true;
			if (!controller.signal.aborted) {
				controller.abort(
					new DOMException("Operation deadline exceeded", "TimeoutError"),
				);
			}
		}, delay);
	}
	return {
		signal: controller.signal,
		abort: (reason?: Error | string | DOMException) => {
			if (!controller.signal.aborted) controller.abort(reason);
		},
		cleanup: () => {
			if (timer !== undefined) clearTimeout(timer);
			control.signal?.removeEventListener("abort", abortFromCaller);
		},
		deadlineTriggered: () => deadlineTriggered,
	};
}

export function isAbortLike<T>(error: T): boolean {
	if (!(error instanceof Error)) return false;
	return error.name === "AbortError" || error.name === "TimeoutError";
}

